SELECT d.id, d.tenant_id, d.sn, d.name, d.product_code, d.product_model, d.product_name, d.product_desc, d.shipment_time, d.package_no, d.contract_no, d.shipment_record_id, d.project_id, d.project_assignment_version, d.customer_id, d.customer_assignment_version, d.site_id, d.site_location_id, d.location_resolution_status, d.location_snapshot, d.location_effective_from, d.location_record_id, d.warranty_start_date, d.warranty_end_date, d.warranty_status, d.conp_version, d.conp_type, d.conp_series, d.conp_mark, d.status, d.remark, d.source_system, d.source_key, d.source_version, d.source_updated_at, d.synced_at, d.sync_status, d.version, d.creator, d.create_time, d.updater, d.update_time, d.deleted

ORDER BY d.id DESC
LIMIT #{query.offset}, #{query.pageSize}

SELECT EXISTS(
    SELECT 1
    FROM ast_device d
    WHERE d.tenant_id = #{query.tenantId}
      AND d.id = #{query.deviceId}
      AND d.deleted = b'0'

)

SELECT d.id, d.sn, d.project_id, d.project_assignment_version, d.status, d.tenant_id FROM ast_device d WHERE d.tenant_id = #{query.tenantId} AND d.sn IN
#{serialNumber}
AND d.deleted = b'0' ORDER BY d.id
